    negated: bool = False


@dataclass
class InList(Expr):
    operand: Optional[Expr] = None
    items: List[Expr] = field(default_factory=list)
    negated: bool = False


@dataclass
class Between(Expr):
    operand: Optional[Expr] = None
    low: Optional[Expr] = None
    high: Optional[Expr] = None
    negated: bool = False


@dataclass
class Like(Expr):
    operand: Optional[Expr] = None
    pattern: Optional[Expr] = None
    negated: bool = False


@dataclass
class FuncCall(Expr):
