    table: str = ""
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


def is_aggregate(node: Optional[Expr]) -> bool:
    """Return whether *node* is an aggregate function call."""
    return isinstance(node, FuncCall) and node.name.upper() in AGGREGATE_NAMES


def children(node: Optional[Expr]) -> Iterator[Expr]:
    """Yield the direct child expressions of *node*."""
    if node is None:
        return
    if isinstance(node, Unary):
        yield node.operand
    elif isinstance(node, Binary):
        yield node.left
        yield node.right
    elif isinstance(node, IsNull):
