    elif isinstance(node, InList):
        yield node.operand
        yield from node.items
    elif isinstance(node, Between):
        yield node.operand
        yield node.low
        yield node.high
    elif isinstance(node, Like):
        yield node.operand
        yield node.pattern
    elif isinstance(node, FuncCall):
        yield from node.args


def walk(node: Optional[Expr]) -> Iterator[Expr]:
    """Yield *node* and every expression nested inside it."""
    if node is None:
        return
    yield node
    for child in children(node):
        yield from walk(child)


def contains_aggregate(node: Optional[Expr]) -> bool:
    """Return whether *node* contains an aggregate function call."""
    return any(is_aggregate(part) for part in walk(node))


def column_refs(node: Optional[Expr]) -> Iterator[Column]:
